window.products.push({"id":920118,"name":"Modway Cabin Modern Farmhouse Wood and Metal Counter Bar Stool in Walnut","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/519SMkONKGS._AC_SL1500_.jpg","description":"Submerge your land-bound activities into a cascading counter stool fit for your transitional seating needs. The Cabin Bar Stool combines a molded bentwood back and waterfall seat, with a fluid form that imbues both an airy and streamlined feel. Cabin’s powder-coated metal frame is solidly constructed to service your needs time and again as a go-to bar stool for light refreshments through to extended conversations.","images":["https://m.media-amazon.com/images/I/519SMkONKGS._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Modway","source_asin":"B07QXY491S","category_path":"Home & Kitchen"},"sku":"BM-920118","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07QXY491S","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07QXY491S","price_pending":true,"merchant_ready":false});
