window.products.push({"id":920212,"name":"Simply Green Solutions Eco 11-Ounce Ceramic Double Wall Thermal Coffee Tumbler w/Silicone Lid - Black","category":"homeandappliances","retail price":15.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/31BpaOM2-SL._AC_.jpg","description":"The Non Paper Cup is a 11-oz reusable and environmentally-friendly alternative to those wasteful coffeehouse paper coffee cups. Featuring an insulating hollow cavity surrounded by two layers of porcelain, the Non Paper Cup coffee mug will keep your drink warmer much longer than a paper cup. Plus, its insulated exterior means you won't need those paper sleeves to protect your hand from a hot drink. The silicone sipping lid also helps to lock in heat and prevent spills.","images":["https://m.media-amazon.com/images/I/31BpaOM2-SL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Simply Green Solutions","source_asin":"B010CEKRNS","category_path":"Home & Kitchen"},"sku":"BM-920212","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B010CEKRNS","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B010CEKRNS","price_pending":true,"merchant_ready":false});
